/* Where Storelib's own accounts came from, and the SEO console's crawl checks (round 45, run after 342). account_attribution keeps one row per account made after this deploy: the first and last touch of the visit to storelib.com that ended in the account (the same shape as orders.first_touch and last_touch, part 60: source, referrer host, UTM tags, landing path and host, time) and the AI assistant each names, when its referrer or utm_source names one (ChatGPT, Perplexity, Copilot, Gemini, Claude and others). Written once by the server for a new account; deleting the account deletes its row. No email, no address, no identifier of the device. seo_crawl_reports keeps the last robots.txt and sitemap file check /admin/seo made of the live site. seo_coverage_groups counts Google's own answers by coverage state, and a partial index finds the listed addresses whose live page is not a 200, says noindex or has a canonical elsewhere. Service role only. No rows change. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.account_attribution (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, first_touch jsonb CHECK (first_touch IS NULL OR jsonb_typeof(first_touch) = 'object'), last_touch jsonb CHECK (last_touch IS NULL OR jsonb_typeof(last_touch) = 'object'), first_ai_source text CHECK (first_ai_source IS NULL OR first_ai_source ~ '^[a-z_]{2,20}$'), last_ai_source text CHECK (last_ai_source IS NULL OR last_ai_source ~ '^[a-z_]{2,20}$'), signed_up_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS account_attribution_created_idx ON public.account_attribution (created_at);
CREATE INDEX IF NOT EXISTS account_attribution_ai_idx ON public.account_attribution (created_at) WHERE first_ai_source IS NOT NULL OR last_ai_source IS NOT NULL;
ALTER TABLE public.account_attribution ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.account_attribution FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.account_attribution TO service_role;
CREATE TABLE IF NOT EXISTS public.seo_crawl_reports (report_kind text PRIMARY KEY CHECK (report_kind IN ('robots', 'sitemaps')), report jsonb NOT NULL CHECK (jsonb_typeof(report) = 'object'), checked_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.seo_crawl_reports ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.seo_crawl_reports FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.seo_crawl_reports TO service_role;
DO $do$ BEGIN IF to_regclass('public.seo_index_status') IS NULL THEN RAISE NOTICE 'part 346: seo_coverage_groups and seo_index_status_conflict_idx skipped, run 342_seo_index_status.sql first'; RETURN; END IF; EXECUTE $e$CREATE INDEX IF NOT EXISTS seo_index_status_conflict_idx ON public.seo_index_status (url) WHERE in_sitemap AND scored_at IS NOT NULL AND (http_status IS DISTINCT FROM 200 OR checks @> '[{"id": "indexable", "state": "fail"}]' OR checks @> '[{"id": "canonical", "state": "fail"}]')$e$; EXECUTE $e$CREATE OR REPLACE FUNCTION public.seo_coverage_groups() RETURNS TABLE (google_status text, coverage_state text, addresses bigint, newest_answer timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT s.google_status, coalesce(s.coverage_state, 'Google gave no coverage state'), count(*), max(s.inspected_at) FROM public.seo_index_status s WHERE s.in_sitemap AND s.inspected_at IS NOT NULL AND s.google_status IN ('indexed', 'not_indexed') GROUP BY 1, 2 ORDER BY 3 DESC $f$$e$; EXECUTE 'REVOKE ALL ON FUNCTION public.seo_coverage_groups() FROM PUBLIC, anon, authenticated'; EXECUTE 'GRANT EXECUTE ON FUNCTION public.seo_coverage_groups() TO service_role'; END $do$;
notify pgrst, 'reload schema';
